from pathlib import Path

p = Path('app/forgot-scan/page.tsx')
s = p.read_text(encoding='utf-8')

old = '  const [ocrBusy, setOcrBusy] = useState(false);\n'
new = '  const [ocrBusy, setOcrBusy] = useState(false);\n  const [videoError, setVideoError] = useState(false);\n'
assert old in s
s = s.replace(old, new, 1)

old = '''  function attachLocalVideo(file?: File) {\n    if (!file || !active) return;\n    if (localVideoUrl) URL.revokeObjectURL(localVideoUrl);\n    const url = URL.createObjectURL(file); setLocalVideoUrl(url); setVideoName(file.name);\n    setRequests((prev) => prev.map((r) => r.id === active.id ? { ...r, videoName: file.name, status: "กำลังตรวจสอบ" } : r));\n  }\n'''
new = '''  function attachLocalVideo(file?: File) {\n    if (!file || !active) return;\n    if (localVideoUrl) URL.revokeObjectURL(localVideoUrl);\n    setVideoError(false);\n    setMessage("");\n    const url = URL.createObjectURL(file); setLocalVideoUrl(url); setVideoName(file.name);\n    setRequests((prev) => prev.map((r) => r.id === active.id ? { ...r, videoName: file.name, status: "กำลังตรวจสอบ" } : r));\n  }\n\n  function attachEvidenceImage(file?: File) {\n    if (!file || !active) return;\n    const url = URL.createObjectURL(file);\n    const img = new Image();\n    img.onload = () => {\n      try {\n        const maxW = 1800, maxH = 1350;\n        const ratio = Math.min(1, maxW / img.width, maxH / img.height);\n        const canvas = document.createElement("canvas");\n        canvas.width = Math.max(1, Math.round(img.width * ratio));\n        canvas.height = Math.max(1, Math.round(img.height * ratio));\n        const ctx = canvas.getContext("2d");\n        if (!ctx) return;\n        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);\n        const image = canvas.toDataURL("image/jpeg", .9);\n        const cap: Capture = { id: crypto.randomUUID(), image, seconds: 0, clipTime: "", cameraDate: "", cameraTime: "" };\n        setRequests((prev) => prev.map((r) => r.id === active.id ? { ...r, captures: [cap], status: "พร้อมจัดทำหลักฐาน" } : r));\n        setMessage("เพิ่มภาพหลักฐาน 1 รูปแล้ว — ตรวจวันที่/เวลาที่เห็นในภาพ แล้วพิมพ์ PDF ได้เลย");\n      } finally {\n        URL.revokeObjectURL(url);\n      }\n    };\n    img.onerror = () => { URL.revokeObjectURL(url); setMessage("อ่านไฟล์ภาพนี้ไม่ได้ กรุณาเลือก JPG หรือ PNG"); };\n    img.src = url;\n  }\n'''
assert old in s
s = s.replace(old, new, 1)

old = '''        {localVideoUrl ? <div className="player"><video ref={videoRef} src={localVideoUrl} playsInline onLoadedMetadata={(e)=>setDuration(e.currentTarget.duration)} onTimeUpdate={(e)=>setCurrentSeconds(e.currentTarget.currentTime)} onPlay={()=>setPlaying(true)} onPause={()=>setPlaying(false)}/><div className="timebar"><b>{fmtTime(currentSeconds)}</b><span>/ {fmtTime(duration)}</span></div><input className="range" type="range" min={0} max={duration||0} step="0.1" value={Math.min(currentSeconds,duration||0)} onChange={(e)=>{const v=videoRef.current;if(v)v.currentTime=Number(e.target.value)}}/><div className="controls"><button onClick={()=>seek(-10)}>−10 วิ</button><button className="play" onClick={togglePlay}>{playing?<Pause size={18}/>:<Play size={18}/>} {playing?"หยุด":"เล่น"}</button><button onClick={()=>seek(10)}>+10 วิ</button><button className="capture" disabled={ocrBusy} onClick={captureFrame}><Camera size={18}/> {ocrBusy?"กำลังอ่านวันเวลา…":"แคปเจอร์ภาพ"}</button></div></div> : <div className="empty">เลือกไฟล์วิดีโอจากเครื่องเพื่อเปิดตัวเล่นและแคปภาพได้ทันที</div>}\n'''
new = '''        {localVideoUrl ? <div className="player"><video ref={videoRef} src={localVideoUrl} playsInline controls preload="metadata" onLoadedMetadata={(e)=>{setVideoError(false);setDuration(e.currentTarget.duration)}} onTimeUpdate={(e)=>setCurrentSeconds(e.currentTarget.currentTime)} onPlay={()=>setPlaying(true)} onPause={()=>setPlaying(false)} onError={()=>{setVideoError(true);setDuration(0);setCurrentSeconds(0);setMessage("ไฟล์วิดีโอนี้ใช้ codec ที่ Chrome บนเครื่องนี้อ่านไม่ได้ — เลือกภาพหลักฐาน 1 รูปด้านล่างแทนได้ทันที")}}/><div className="timebar"><b>{fmtTime(currentSeconds)}</b><span>/ {fmtTime(duration)}</span></div>{!videoError&&<><input className="range" type="range" min={0} max={duration||0} step="0.1" value={Math.min(currentSeconds,duration||0)} onChange={(e)=>{const v=videoRef.current;if(v)v.currentTime=Number(e.target.value)}}/><div className="controls"><button onClick={()=>seek(-10)}>−10 วิ</button><button className="play" onClick={togglePlay}>{playing?<Pause size={18}/>:<Play size={18}/>} {playing?"หยุด":"เล่น"}</button><button onClick={()=>seek(10)}>+10 วิ</button><button className="capture" disabled={ocrBusy} onClick={captureFrame}><Camera size={18}/> {ocrBusy?"กำลังอ่านวันเวลา…":"แคปเจอร์ภาพ"}</button></div></>} {videoError&&<label className="video-fallback"><Camera size={20}/><strong>วิดีโอเล่นไม่ได้ — เลือกภาพหลักฐาน 1 รูปแทน</strong><small>รองรับ JPG / PNG และนำไปพิมพ์ครึ่ง A4 ได้ทันที</small><input type="file" accept="image/jpeg,image/png,image/webp" onChange={(e)=>attachEvidenceImage(e.target.files?.[0])}/></label>}</div> : <div className="empty">เลือกไฟล์วิดีโอจากเครื่องเพื่อเปิดตัวเล่นและแคปภาพได้ทันที</div>}\n'''
assert old in s
s = s.replace(old, new, 1)

old = '.controls .capture:disabled{opacity:.65}.captures{display:grid;'
new = '.controls .capture:disabled{opacity:.65}.video-fallback{margin:10px 12px 0;padding:14px;border:2px dashed #f59e0b;border-radius:12px;background:#fff7ed;color:#9a3412;display:flex;flex-direction:column;align-items:center;gap:5px;text-align:center;cursor:pointer}.video-fallback input{display:none}.video-fallback small{font-size:12px}.captures{display:grid;'
assert old in s
s = s.replace(old, new, 1)

p.write_text(s, encoding='utf-8')
